\begin{definition}
\label{definition-symmetric-monoidal-category}
A quadruple $(\mathcal{C}, \otimes, \phi, \psi)$ where
$\mathcal{C}$ is a category,
$\otimes : \mathcal{C} \otimes \mathcal{C} \to \mathcal{C}$ is a functor,
$\phi$ is an associativity constraint, and
$\psi$ is a commutativity constraint compatible with $\phi$
is called a {\it symmetric monoidal category} if there exists
a unit.
\end{definition}

\begin{lemma}
\label{lemma-symmetric-monoidal-coherence}
In a symmetric monoidal category
$\mathcal{C}, \otimes, \phi, \psi, \mathbf{1}, 1$
we have
\begin{enumerate}
\item the arrows $1 \circ \psi, 1 :
\mathbf{1} \otimes \mathbf{1} \to \mathbf{1}$ agree,
\item the arrows $\text{id}_X \otimes l_Y,
(l_X \otimes \text{id}) \circ (\psi \otimes \text{id}_Y):
X \otimes \mathbf{1} \otimes Y \to X \otimes Y$ agree,
\end{enumerate}
A symmetric monoidal category satisfies the assumptions of
\cite[Theorem 5.1]{associativity}.
\end{lemma}

